// src/components/Pricing.jsx

import React from 'react';
import { FaRunning, FaTicketAlt, FaCalendarAlt } from 'react-icons/fa';

// --- Data for the pricing plans (no changes here) ---
const pricingPlans = [
  {
    icon: <FaRunning size={30} />,
    title: 'FREE TRIAL',
    subtitle: 'For First-Time Participants',
    price: '0',
    priceDetails: '/1 Session',
    features: [
      'Guided warm-up session',
      '1-hour community run',
      'Light post-run treats',
      'Networking with fellow runners',
      'Basic fitness assessment',
    ],
    buttonText: 'START FREE TRIAL',
    featured: false,
  },
  {
    icon: <FaTicketAlt size={30} />,
    title: 'PAY-PER-RUN',
    subtitle: 'Flexible Sessions',
    originalPrice: '149',
    discount: '34% OFF',
    price: '99',
    priceDetails: '/Per Session',
    features: [
      'Guided warm-up & cooldown',
      '1-hour structured run',
      'Healthy energy boosters',
      'Community networking',
    ],
    buttonText: 'CHOOSE PAY-PER-RUN',
    featured: true,
  },
  {
    icon: <FaCalendarAlt size={30} />,
    title: 'MONTHLY MEMBERSHIP',
    subtitle: 'Unlimited Access',
    originalPrice: '499',
    discount: '40% OFF',
    price: '299',
    priceDetails: '/Per Month',
    features: [
      'Unlimited weekly runs',
      'Personal fitness consultation',
      'Nutritious post-run meals',
      'Exclusive community events',
      'Priority event booking',
    ],
    buttonText: 'CHOOSE MONTHLY MEMBERSHIP',
    featured: false,
  },
];


// --- Main Pricing Component ---
const Pricing = () => {
  return (
    <section style={styles.pricingSection}>
      <div style={styles.container}>
        
        {/* === TOP ROW: Contains the first two cards === */}
        <div style={styles.topRow}>
          {pricingPlans.slice(0, 2).map((plan, index) => (
            <div key={index} style={{ ...styles.card, ...(plan.featured ? styles.featuredCard : {}) }}>
              <div style={styles.iconContainer}>{plan.icon}</div>
              <h2 style={styles.title}>{plan.title}</h2>
              <p style={styles.subtitle}>{plan.subtitle}</p>
              
              <div style={styles.priceContainer}>
                {plan.originalPrice && (
                  <span style={styles.originalPrice}>₹{plan.originalPrice}</span>
                )}
                {plan.discount && (
                  <span style={styles.discountBadge}>{plan.discount}</span>
                )}
              </div>
              
              <p style={styles.price}>
                <span style={styles.currency}>₹</span>
                {plan.price}
                <span style={styles.priceDetails}>{plan.priceDetails}</span>
              </p>
              
              <h3 style={styles.whatsIncluded}>WHAT'S INCLUDED:</h3>
              <ul style={styles.featuresList}>
                {plan.features.map((feature, i) => (
                  <li key={i} style={styles.featureItem}>
                    <span style={styles.checkmark}>✓</span> {feature}
                  </li>
                ))}
              </ul>

              <button style={styles.button}>{plan.buttonText} →</button>
            </div>
          ))}
        </div>

        {/* === BOTTOM ROW: Contains the third card === */}
        <div style={styles.bottomRow}>
          {pricingPlans.slice(2, 3).map((plan, index) => (
            <div key={index} style={{ ...styles.card, ...(plan.featured ? styles.featuredCard : {}) }}>
            <div style={styles.iconContainer}>{plan.icon}</div>
            <h2 style={styles.title}>{plan.title}</h2>
            <p style={styles.subtitle}>{plan.subtitle}</p>
            
            <div style={styles.priceContainer}>
              {plan.originalPrice && (
                <span style={styles.originalPrice}>₹{plan.originalPrice}</span>
              )}
              {plan.discount && (
                <span style={styles.discountBadge}>{plan.discount}</span>
              )}
            </div>
            
            <p style={styles.price}>
              <span style={styles.currency}>₹</span>
              {plan.price}
              <span style={styles.priceDetails}>{plan.priceDetails}</span>
            </p>
            
            <h3 style={styles.whatsIncluded}>WHAT'S INCLUDED:</h3>
            <ul style={styles.featuresList}>
              {plan.features.map((feature, i) => (
                <li key={i} style={styles.featureItem}>
                  <span style={styles.checkmark}>✓</span> {feature}
                </li>
              ))}
            </ul>

            <button style={styles.button}>{plan.buttonText} →</button>
          </div>
          ))}
        </div>

      </div>
    </section>
  );
};


// --- Styles ---
const styles = {
    pricingSection: {
      backgroundColor: '#121212',
      padding: '64px 24px',
      fontFamily: 'sans-serif',
      color: '#ffffff',
    },
    // UPDATED: The main container now stacks the rows vertically and centers them
    container: {
      maxWidth: '1200px',
      margin: '0 auto',
      display: 'flex',
      flexDirection: 'column', // Stack rows on top of each other
      alignItems: 'center', // Center the rows/cards
      gap: '32px', // Space between the top row and the bottom card
    },
    // NEW: Style for the top row of cards
    topRow: {
        display: 'flex',
        justifyContent: 'center',
        gap: '32px',
        flexWrap: 'wrap', // Allows cards to stack on smaller screens
        width: '100%',
    },
    // NEW: Style for the bottom row (to ensure centering)
    bottomRow: {
        display: 'flex',
        justifyContent: 'center',
        width: '100%',
    },
    card: {
      backgroundColor: '#1A1A1A',
      padding: '40px',
      borderRadius: '20px',
      border: '1px solid #333',
      width: '350px',
      display: 'flex',
      flexDirection: 'column',
      textAlign: 'left',
    },
    featuredCard: {
      border: '1px solid #FF8732',
      boxShadow: '0 0 25px rgba(255, 135, 50, 0.3)',
    },
    iconContainer: {
      backgroundColor: '#2C2C2C',
      width: '60px',
      height: '60px',
      borderRadius: '12px',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      marginBottom: '24px',
      color: '#FF8732',
    },
    title: {
      fontSize: '1.5rem',
      fontWeight: 'bold',
      margin: 0,
    },
    subtitle: {
      color: '#A0A0A0',
      marginBottom: '24px',
    },
    priceContainer: {
        display: 'flex',
        alignItems: 'center',
        gap: '10px',
        height: '24px',
    },
    originalPrice: {
        fontSize: '1.2rem',
        color: '#A0A0A0',
        textDecoration: 'line-through',
    },
    discountBadge: {
        backgroundColor: '#28a745',
        color: '#ffffff',
        padding: '4px 8px',
        borderRadius: '6px',
        fontSize: '0.8rem',
        fontWeight: 'bold',
    },
    price: {
      fontSize: '4rem',
      fontWeight: 'bold',
      margin: '8px 0',
    },
    currency: {
        fontSize: '2rem',
        color: '#A0A0A0',
        marginRight: '8px',
    },
    priceDetails: {
      fontSize: '1rem',
      fontWeight: 'normal',
      color: '#A0A0A0',
    },
    whatsIncluded: {
      color: '#FF8732',
      fontSize: '0.9rem',
      fontWeight: 'bold',
      margin: '24px 0 16px 0',
      letterSpacing: '1px',
    },
    featuresList: {
      listStyle: 'none',
      padding: 0,
      margin: 0,
      flexGrow: 1,
    },
    featureItem: {
      marginBottom: '12px',
      display: 'flex',
      alignItems: 'center',
    },
    checkmark: {
        color: '#FF8732',
        marginRight: '12px',
        fontWeight: 'bold',
    },
    button: {
      backgroundColor: '#FF8732',
      color: '#ffffff',
      border: 'none',
      borderRadius: '12px',
      padding: '16px',
      fontSize: '1rem',
      fontWeight: 'bold',
      cursor: 'pointer',
      marginTop: '32px',
      transition: 'background-color 0.3s ease',
    },
};

export default Pricing;
